insert into public.course_content_draft (course_id, what_you_build, what_you_learn, session, starter_code, test_it_out, troubleshooting, resources, tier, change_note)
values (
  5,
  $wyb$A command-line tool that reads a raw meeting transcript - from a file or pasted text - and uses Claude or Gemini (your own key, your choice) to extract the decisions that were made, a clean list of action items with an owner and deadline for each, and a short summary, then renders all of it as a polished Markdown file you can drop straight into Notion, Slack, or a wiki page.$wyb$,
  $wyl$[
  "Read raw text input reliably from a file or stdin, and reject empty input before it reaches the AI",
  "Design an AI prompt using bracket markers instead of fragile JSON",
  "Parse a real (and a broken) AI reply without ever inventing missing information",
  "Normalize vague AI answers like \"TBD\" or blank into one clear default",
  "Render structured data into a Markdown table",
  "Wire multiple small files together into one command-line tool",
  "Call the AI through your own key safely, with a capped max_tokens"
]$wyl$::jsonb,
  $sess${
  "model": "Google Gemini (gemini-flash-latest) or Claude Haiku 4.5 - your choice, see sdt_ai.py setup",
  "builds": [
    {
      "time": "15 min",
      "steps": [
        {
          "prompt": "requests\npython-dotenv\n",
          "verify": "requirements.txt sits directly inside your project folder, not in a subfolder. The next step installs everything it lists.",
          "instruction": "Make an empty folder for this project and open it in your code editor (in VS Code: File > Open Folder). Inside it, create `requirements.txt` with this content - it lists every library this project uses:"
        },
        {
          "instruction": "Set up Python for this project (once, about 5 minutes). Check your version with `python3 --version` on Mac/Linux or `py --version` on Windows. If it is missing or older than 3.10, install the latest Python from python.org/downloads (on Windows, tick \"Add python.exe to PATH\" on the installer's first screen), then open a new terminal. Now open a terminal in your project folder (in VS Code: Terminal > New Terminal) and run the commands below for your system. They create a virtual environment - a private set of libraries for this project only - and install everything requirements.txt lists.",
          "prompt": "# Mac / Linux\npython3 -m venv .venv\nsource .venv/bin/activate\npython -m pip install -r requirements.txt\n\n# Windows (PowerShell)\npy -m venv .venv\n.venv\\Scripts\\Activate.ps1\npython -m pip install -r requirements.txt\n\n# Windows says \"running scripts is disabled\"? Run this once, then the Activate line again:\n#   Set-ExecutionPolicy -Scope CurrentUser RemoteSigned\n# Ubuntu/Debian says venv or ensurepip is not available? Run: sudo apt install python3-venv",
          "verify": "Your terminal prompt now starts with (.venv), and the install ended with \"Successfully installed\". Each time you open a new terminal for this project, run the activate line again first - while it is active, plain `python` works on every system, and that is the command every step below uses."
        },
        {
          "prompt": "\"\"\"\nSocial Dev Technologies - your connection to the AI.\n\nYou have TWO ways to power this file. Pick ONE and set it in your .env:\n\n  AI_PROVIDER=gemini    -> your own FREE Google Gemini API key\n  AI_PROVIDER=claude    -> your own Claude/Anthropic API key\n\nEvery project in this course calls ask_ai(...) the exact same way no\nmatter which one you pick - this file is the only place that changes.\n\nSETUP - OPTION 1: Gemini (free, no billing needed):\n\n  1. Go to https://aistudio.google.com/apikey and sign in with any Google\n     account. Click \"Create API key\" - free, no card required.\n  2. In the same folder as this file, create a file named exactly: .env\n  3. Put these two lines inside it:\n\n         AI_PROVIDER=gemini\n         GEMINI_API_KEY=paste_your_own_key_here\n\nSETUP - OPTION 2: Claude (if you already have a paid Claude account):\n\n  1. Go to https://console.anthropic.com/settings/keys and create an API\n     key. This needs billing set up on your Anthropic account - it is a\n     separate thing from a claude.ai Pro subscription, and is billed by\n     Anthropic based on what you actually use.\n  2. In your .env file, put these two lines instead:\n\n         AI_PROVIDER=claude\n         ANTHROPIC_API_KEY=paste_your_own_key_here\n\nNever share either key or put it on GitHub - each one is billed to YOUR\naccount. That's it. Every project in this course reuses this same file.\n\"\"\"\n\nimport os\nimport time\n\nimport requests\nfrom dotenv import load_dotenv\n\n# Reads the .env file sitting next to your project and loads your keys.\nload_dotenv()\n\n# \"gemini-flash-latest\" is Google's name for whatever its newest Flash model\n# is, so this file keeps working when Google retires an older model - which\n# it does regularly. You can pin one specific model with GEMINI_MODEL=... in\n# your .env, but if you ever get a \"not available\" error, delete that line.\nGEMINI_MODEL = os.environ.get(\"GEMINI_MODEL\", \"gemini-flash-latest\")\nGEMINI_URL_TEMPLATE = \"https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent\"\n\n# Gemini \"thinks\" before it answers, and that hidden thinking counts toward\n# the same token limit as the answer itself. With a small max_tokens (the\n# 50-300 used for short replies in this course) the thinking could use up\n# the whole limit and the answer would come back empty. So this file turns\n# thinking down to its minimum (these projects don't need it) and gives\n# Gemini this many extra tokens on top of your max_tokens for whatever\n# thinking is left.\nTHINKING_ALLOWANCE = 1024\n\nCLAUDE_MODEL = os.environ.get(\"CLAUDE_MODEL\", \"claude-haiku-4-5\")\nANTHROPIC_URL = \"https://api.anthropic.com/v1/messages\"\nANTHROPIC_VERSION = \"2023-06-01\"\n\n# Both AIs occasionally answer \"overloaded\" during busy periods (Gemini's\n# free tier especially). That's not your code being wrong - retrying a\n# couple of times almost always gets a real answer, so it's built in here\n# rather than left for every project to handle separately.\nMAX_ATTEMPTS = 3\nRETRY_DELAY_SECONDS = 3\n\n\nclass AIError(Exception):\n    \"\"\"Something went wrong talking to the AI. The message explains what.\"\"\"\n\n\ndef _get_provider():\n    \"\"\"\n    Reads AI_PROVIDER from .env. Falls back to guessing from whichever key\n    is actually present, so forgetting to set AI_PROVIDER explicitly\n    doesn't crash a setup that only has one key configured.\n    \"\"\"\n    provider = os.environ.get(\"AI_PROVIDER\", \"\").strip().lower()\n    if provider in (\"gemini\", \"claude\"):\n        return provider\n\n    if os.environ.get(\"GEMINI_API_KEY\"):\n        return \"gemini\"\n    if os.environ.get(\"ANTHROPIC_API_KEY\"):\n        return \"claude\"\n\n    raise AIError(\n        \"No AI provider configured.\\n\"\n        \"Add ONE of these pairs to your .env file:\\n\\n\"\n        \"    AI_PROVIDER=gemini\\n\"\n        \"    GEMINI_API_KEY=paste_your_free_key_here\\n\\n\"\n        \"  ...or...\\n\\n\"\n        \"    AI_PROVIDER=claude\\n\"\n        \"    ANTHROPIC_API_KEY=paste_your_own_key_here\\n\\n\"\n        \"Get a free Gemini key at https://aistudio.google.com/apikey\"\n    )\n\n\ndef _ask_gemini(prompt, system=None, max_tokens=1000):\n    api_key = os.environ.get(\"GEMINI_API_KEY\")\n    if not api_key:\n        raise AIError(\n            \"AI_PROVIDER is set to gemini but no GEMINI_API_KEY was found.\\n\"\n            \"Get a free key at https://aistudio.google.com/apikey and add \"\n            \"it to .env:\\n\"\n            \"    GEMINI_API_KEY=paste_your_own_key_here\"\n        )\n\n    generation_config = {\"maxOutputTokens\": max_tokens + THINKING_ALLOWANCE}\n    # thinkingBudget 0 = \"as little thinking as possible\". Pro models can't\n    # turn thinking down and reject this setting, so it's left off for them.\n    if \"-pro\" not in GEMINI_MODEL:\n        generation_config[\"thinkingConfig\"] = {\"thinkingBudget\": 0}\n\n    payload = {\n        \"contents\": [{\"role\": \"user\", \"parts\": [{\"text\": prompt}]}],\n        \"generationConfig\": generation_config,\n    }\n    if system:\n        payload[\"systemInstruction\"] = {\"parts\": [{\"text\": system}]}\n\n    url = GEMINI_URL_TEMPLATE.format(model=GEMINI_MODEL)\n    # The key goes in a header rather than the URL, so it never shows up in\n    # an error message or traceback you might paste somewhere for help.\n    headers = {\"x-goog-api-key\": api_key}\n\n    last_problem = \"no response\"\n    for attempt in range(MAX_ATTEMPTS):\n        try:\n            response = requests.post(url, headers=headers, json=payload, timeout=90)\n        except requests.RequestException:\n            raise AIError(\n                \"Could not reach Gemini. Check your internet connection and try again.\"\n            ) from None\n\n        if response.status_code in (500, 503):\n            last_problem = f\"Gemini is busy ({response.status_code} - high demand on the free tier)\"\n            if attempt < MAX_ATTEMPTS - 1:\n                time.sleep(RETRY_DELAY_SECONDS)\n            continue\n\n        if response.status_code == 429:\n            raise AIError(\n                \"Gemini says you've hit the free tier's rate limit. Wait a \"\n                \"minute and try again - the free tier only allows a \"\n                \"limited number of requests per minute.\"\n            )\n\n        if response.status_code == 404:\n            if os.environ.get(\"GEMINI_MODEL\"):\n                advice = (\n                    \"Your .env file sets GEMINI_MODEL - delete that line so this \"\n                    \"file uses its default model, then try again.\"\n                )\n            else:\n                advice = \"Check the course page for an updated copy of sdt_ai.py.\"\n            raise AIError(\n                f'Gemini says the model \"{GEMINI_MODEL}\" isn\\'t available to your '\n                f\"API key - Google retires older models.\\n{advice}\\n\"\n                f\"Details: {response.text[:300]}\"\n            )\n\n        if response.status_code == 400:\n            # If a future Gemini model ever refuses the thinking setting\n            # above, ask again without it instead of failing.\n            if \"thinkingConfig\" in generation_config and \"thinking\" in response.text.lower():\n                del generation_config[\"thinkingConfig\"]\n                last_problem = \"Gemini rejected the thinking setting\"\n                continue\n            raise AIError(\n                f\"Gemini rejected the request - double check your GEMINI_API_KEY \"\n                f\"is correct: {response.text[:300]}\"\n            )\n\n        if response.status_code != 200:\n            raise AIError(\n                f\"Gemini returned an error (status {response.status_code}): {response.text[:300]}\"\n            )\n\n        data = response.json()\n        candidates = data.get(\"candidates\") or []\n        if not candidates:\n            block_reason = (data.get(\"promptFeedback\") or {}).get(\"blockReason\")\n            if block_reason:\n                raise AIError(f\"Gemini refused the prompt ({block_reason}). Try rephrasing it.\")\n            raise AIError(f\"Unexpected reply from Gemini: {data}\")\n        candidate = candidates[0]\n        finish_reason = candidate.get(\"finishReason\")\n\n        # A response can come back with no text because Gemini's safety\n        # filters blocked it (finishReason == \"SAFETY\"), not because of a\n        # network problem - so this is not retried like the cases above.\n        if finish_reason == \"SAFETY\":\n            raise AIError(\"Gemini declined to answer (safety filter). Try rephrasing your prompt.\")\n\n        # An answer can arrive split across several parts, so join them all.\n        # Any part marked \"thought\" is Gemini's thinking, not its answer.\n        parts = (candidate.get(\"content\") or {}).get(\"parts\") or []\n        text = \"\".join(part.get(\"text\", \"\") for part in parts if not part.get(\"thought\"))\n        if not text:\n            if finish_reason == \"MAX_TOKENS\":\n                raise AIError(\n                    \"Gemini ran out of room before it wrote any answer - its thinking \"\n                    f\"used up all {generation_config['maxOutputTokens']} tokens it was \"\n                    \"allowed. Raise max_tokens in this ask_ai(...) call (try \"\n                    f\"max_tokens={max(max_tokens * 2, 4000)}) and run it again.\"\n                )\n            raise AIError(\n                f\"Gemini sent back an empty answer (finishReason: {finish_reason}). \"\n                \"Try again, or rephrase your prompt.\"\n            )\n\n        usage = data.get(\"usageMetadata\") or {}\n        return {\n            \"text\": text,\n            \"input_tokens\": usage.get(\"promptTokenCount\"),\n            \"output_tokens\": usage.get(\"candidatesTokenCount\"),\n        }\n\n    raise AIError(\n        f\"Gemini was unavailable after {MAX_ATTEMPTS} tries ({last_problem}). \"\n        \"This happens sometimes on the free tier during high demand - wait \"\n        \"a minute and try again.\"\n    )\n\n\ndef _ask_claude(prompt, system=None, max_tokens=1000):\n    api_key = os.environ.get(\"ANTHROPIC_API_KEY\")\n    if not api_key:\n        raise AIError(\n            \"AI_PROVIDER is set to claude but no ANTHROPIC_API_KEY was found.\\n\"\n            \"Create one at https://console.anthropic.com/settings/keys and \"\n            \"add it to .env:\\n\"\n            \"    ANTHROPIC_API_KEY=paste_your_own_key_here\"\n        )\n\n    payload = {\n        \"model\": CLAUDE_MODEL,\n        \"max_tokens\": max_tokens,\n        \"messages\": [{\"role\": \"user\", \"content\": prompt}],\n    }\n    if system:\n        payload[\"system\"] = system\n\n    last_problem = \"no response\"\n    for attempt in range(MAX_ATTEMPTS):\n        try:\n            response = requests.post(\n                ANTHROPIC_URL,\n                headers={\n                    \"x-api-key\": api_key,\n                    \"anthropic-version\": ANTHROPIC_VERSION,\n                    \"Content-Type\": \"application/json\",\n                },\n                json=payload,\n                timeout=90,\n            )\n        except requests.RequestException:\n            raise AIError(\n                \"Could not reach Claude. Check your internet connection and try again.\"\n            ) from None\n\n        # 529 is Anthropic's \"overloaded\" - like Gemini's 503, a retry\n        # usually works.\n        if response.status_code in (500, 503, 529):\n            last_problem = f\"Claude is busy ({response.status_code} - overloaded)\"\n            if attempt < MAX_ATTEMPTS - 1:\n                time.sleep(RETRY_DELAY_SECONDS)\n            continue\n\n        try:\n            data = response.json()\n        except ValueError:\n            raise AIError(f\"Unexpected reply from Claude (status {response.status_code}).\") from None\n\n        if response.status_code == 401:\n            raise AIError(\n                \"Claude rejected your ANTHROPIC_API_KEY - double check it was copied correctly.\"\n            )\n\n        if response.status_code == 429:\n            raise AIError(\"Claude says you've hit your rate or usage limit. Wait a moment and try again.\")\n\n        if response.status_code == 404:\n            if os.environ.get(\"CLAUDE_MODEL\"):\n                advice = (\n                    \"Your .env file sets CLAUDE_MODEL - delete that line so this \"\n                    \"file uses its default model, then try again.\"\n                )\n            else:\n                advice = \"Check the course page for an updated copy of sdt_ai.py.\"\n            raise AIError(\n                f'Claude says the model \"{CLAUDE_MODEL}\" isn\\'t available to your '\n                f\"API key.\\n{advice}\"\n            )\n\n        if \"error\" in data or response.status_code != 200:\n            error = data.get(\"error\") or {}\n            message = error.get(\"message\") if isinstance(error, dict) else str(error)\n            raise AIError(\n                f\"Claude returned an error (status {response.status_code}): \"\n                f\"{message or str(data)[:300]}\"\n            )\n\n        text = \"\".join(\n            block.get(\"text\", \"\") for block in data.get(\"content\", []) if block.get(\"type\") == \"text\"\n        )\n        if not text:\n            raise AIError(\n                f\"Claude sent back an empty answer (stop_reason: {data.get('stop_reason')}). \"\n                \"Try again, or rephrase your prompt.\"\n            )\n\n        usage = data.get(\"usage\") or {}\n        return {\n            \"text\": text,\n            \"input_tokens\": usage.get(\"input_tokens\"),\n            \"output_tokens\": usage.get(\"output_tokens\"),\n        }\n\n    raise AIError(\n        f\"Claude was unavailable after {MAX_ATTEMPTS} tries ({last_problem}). \"\n        \"Wait a minute and try again.\"\n    )\n\n\ndef ask_ai_detailed(prompt, system=None, max_tokens=1000, project=None):\n    \"\"\"\n    Same as ask_ai, but returns the whole reply as a dict.\n\n        result = ask_ai_detailed(\"Summarise this\", max_tokens=200)\n        print(result[\"text\"])\n    \"\"\"\n    provider = _get_provider()\n    if provider == \"gemini\":\n        return _ask_gemini(prompt, system=system, max_tokens=max_tokens)\n    return _ask_claude(prompt, system=system, max_tokens=max_tokens)\n\n\ndef ask_ai(prompt, system=None, max_tokens=1000, project=None):\n    \"\"\"\n    Send a question to the AI and get the answer back as text.\n\n        answer = ask_ai(\"Write a haiku about Lagos traffic\")\n        print(answer)\n\n    prompt      - what you want the AI to do. This is the important part.\n    system      - optional. Sets the AI's role, e.g. \"You are a careful editor.\"\n    max_tokens  - roughly how long the answer may be. 1000 is plenty for most.\n    project     - unused, kept so call sites read the same across every\n                  project regardless of which AI is behind this file.\n\n    Works identically whichever provider your .env is set to - every\n    project in this course calls this one function and never needs to\n    know which AI is actually answering.\n\n    Returns the AI's answer as a plain string.\n    Raises AIError with a readable message if something is wrong.\n    \"\"\"\n    return ask_ai_detailed(prompt, system=system, max_tokens=max_tokens, project=project)[\"text\"]\n\n\nif __name__ == \"__main__\":\n    # Running this file directly checks that your setup works.\n    print(\"Testing your AI connection...\\n\")\n    try:\n        provider = _get_provider()\n        model = GEMINI_MODEL if provider == \"gemini\" else CLAUDE_MODEL\n        result = ask_ai_detailed(\"Say hello in exactly five words.\", max_tokens=50)\n        print(f\"Provider: {provider} ({model})\")\n        print(\"The AI said:\", result[\"text\"])\n        print(\"\\nYour setup works. You are ready to build.\")\n    except AIError as problem:\n        print(\"Setup problem:\\n\")\n        print(problem)\n",
          "verify": "Nothing to check yet — you'll test this file once your .env is filled in, in the next step.",
          "instruction": "Create `sdt_ai.py` with this code — copy it exactly, you'll never edit it. This is the ONLY file that talks to the AI in this whole project:"
        },
        {
          "prompt": "# OPTION 1: your own free Gemini key (recommended - no billing needed)\n# Get one free at https://aistudio.google.com/apikey - no credit card needed\nAI_PROVIDER=gemini\nGEMINI_API_KEY=paste_your_own_key_here\n\n# OPTION 2: your own Claude/Anthropic key (comment OPTION 1 out above,\n# uncomment these two lines instead - needs billing set up on your own\n# Anthropic account)\n# Get one at https://console.anthropic.com/settings/keys\n# AI_PROVIDER=claude\n# ANTHROPIC_API_KEY=paste_your_own_key_here\n",
          "verify": "Run `python sdt_ai.py` - it should print which provider you're using, then `The AI said: ...`, and end with `Your setup works. You are ready to build.` If you see `No AI provider configured` instead, check that .env sits next to sdt_ai.py and that AI_PROVIDER plus its matching key are both uncommented.",
          "instruction": "Create `.env` in the same folder with this content. Pick ONE AI option (Gemini or Claude) below."
        }
      ],
      "title": "Connect your AI (Gemini or Claude)",
      "number": 1,
      "description": "Set up the one file every build in this project calls to reach the AI, before writing the formatter that actually uses it."
    },
    {
      "time": "15 min",
      "steps": [
        {
          "prompt": "Weekly Product Sync - Sept 1\n\nAttendees: Amaka, Tunde, Chidi, Priya (dialed in late)\n\nAmaka: ok let's get started, we're behind on the onboarding redesign.\nTunde: yeah the Figma files are done, dev just hasn't picked it up yet\nChidi: I can start on it Monday if nobody else is on it\nAmaka: sounds good, go ahead Chidi\n\nAmaka: also, we need to decide on the pricing page - do we keep the\nold three-tier layout or switch to the new single-price page marketing\nsent over?\nTunde: I vote we switch, the old one is confusing people, support tickets\nabout pricing are up like 30% this month\nChidi: agreed, let's switch\nAmaka: ok, decision made - we're moving to the single-price layout\n\nPriya joins late: sorry I'm late, what did I miss\n\nAmaka: quick recap - Chidi's starting the onboarding redesign Monday,\nand we're switching the pricing page to the single-price layout\n\nTunde: one more thing, someone needs to email the beta testers about\nthe pricing change before we ship it, don't want them blindsided\nAmaka: good call\nChidi: I don't think that's on me, I'm heads down on onboarding\nTunde: I can't this week either, I'm out Thursday and Friday\nAmaka: ...ok someone needs to own that, let's figure it out after the call\n\nAmaka: last thing - can we get the pricing switch live by end of month?\nTunde: should be doable, maybe the 28th\nAmaka: let's lock the 28th as the target then\n\nPriya: quick question, are we still doing the quarterly review next week?\nAmaka: yes, same time, I'll send the invite\n\nAmaka: ok that's everything, thanks all\n",
          "verify": "Open the file and confirm it has multiple speakers, at least one clear decision (switching the pricing page layout), and one action item nobody clearly owns (emailing the beta testers - both Chidi and Tunde turn it down on the call). You'll use that gap to test the formatter in Build 3.",
          "instruction": "Create `sample_transcript.txt` - a messy, realistic meeting transcript to test with:"
        },
        {
          "prompt": "\"\"\"\nStep 1 of the Meeting Notes Formatter Agent.\n\nThis file has one job: get the raw meeting transcript text, however the\nstudent wants to supply it - a file path, or pasted straight into the\nterminal (stdin). Nothing here talks to the AI; that's formatter.py.\n\"\"\"\n\nimport os\nimport sys\nimport tempfile\n\n# Stop after this many characters.\n#\n# This is a MONEY decision, not a technical one (see article.py in the\n# Social Post Generator project for the same idea). A one-hour meeting\n# transcript can run to 20,000+ characters once you include filler words\n# (\"um\", \"so\", \"yeah\") and speaker labels. The AI doesn't need every\n# \"um\" to spot the decisions and action items - 8000 characters is\n# roughly a 45-60 minute meeting's worth of substance, and sending more\n# than that mostly pays for filler, not better output.\nMAX_CHARACTERS = 8000\n\n\ndef get_transcript_text(file_path=None):\n    \"\"\"\n    Returns the raw transcript text, from a file or from stdin.\n\n        text = get_transcript_text(\"sample_transcript.txt\")\n\n    Pass no file_path (or None) to read from stdin instead - useful if\n    you want to pipe a transcript straight in:\n\n        python main.py < my_meeting.txt\n\n    Raises a clear error if the file is missing, or the transcript is\n    too short to contain anything worth formatting.\n    \"\"\"\n    if file_path:\n        try:\n            with open(file_path, \"r\", encoding=\"utf-8\") as f:\n                text = f.read()\n        except FileNotFoundError:\n            raise ValueError(\n                f\"Could not find a file at '{file_path}'.\\n\"\n                f\"Check the path is correct and try again.\"\n            )\n    else:\n        text = sys.stdin.read()\n\n    text = text.strip()\n\n    if len(text) < 20:\n        raise ValueError(\n            \"That transcript looks empty (or almost empty).\\n\"\n            \"Paste in some real meeting notes - even a few bullet points \"\n            \"of what was discussed - and try again.\"\n        )\n\n    return text[:MAX_CHARACTERS]\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check it works:  python notes.py\n    print(\"Reading sample_transcript.txt...\\n\")\n    text = get_transcript_text(\"sample_transcript.txt\")\n    print(f\"Got {len(text)} characters. First 200:\\n\")\n    print(text[:200])\n\n    print(\"\\n--- Testing a missing file path ---\")\n    try:\n        get_transcript_text(\"does_not_exist.txt\")\n        print(\"ERROR: should have raised ValueError\")\n    except ValueError as problem:\n        print(\"Correctly raised an error:\")\n        print(problem)\n\n    # A transcript with almost nothing in it (a mis-click, an empty paste)\n    # should be rejected here - with a message telling the student what\n    # to do - rather than reaching the AI and paying for an AI call on garbage.\n    print(\"\\n--- Testing the empty-transcript guard ---\")\n    fd, tmp_path = tempfile.mkstemp(suffix=\".txt\")\n    try:\n        with os.fdopen(fd, \"w\") as f:\n            f.write(\"hi\")\n        get_transcript_text(tmp_path)\n        print(\"ERROR: should have raised ValueError\")\n    except ValueError as problem:\n        print(\"Correctly raised an error:\")\n        print(problem)\n    finally:\n        os.remove(tmp_path)\n",
          "verify": "Run `python notes.py`. You should see:\nReading sample_transcript.txt...\n\nGot 1535 characters. First 200:\n\nWeekly Product Sync - Sept 1...\n\n--- Testing a missing file path ---\nCorrectly raised an error:\nCould not find a file at 'does_not_exist.txt'.\nCheck the path is correct and try again.\n\n--- Testing the empty-transcript guard ---\nCorrectly raised an error:\nThat transcript looks empty (or almost empty).\nPaste in some real meeting notes - even a few bullet points of what was discussed - and try again.",
          "instruction": "Create `notes.py` with this code:"
        }
      ],
      "title": "Read the raw meeting notes",
      "number": 2,
      "goFurther": "Swap in a real transcript instead of the sample - copy any messy meeting notes you have (or a rough Zoom transcript export) into a new .txt file and confirm get_transcript_text() reads it exactly the same way.",
      "description": "Before you can format anything, you need to reliably get the transcript text into your program - from a file, or piped in directly - and reject anything too short to be worth an AI call. Get this boring part right first so nothing downstream ever receives blank input."
    },
    {
      "time": "35 min",
      "steps": [
        {
          "prompt": "\"\"\"\nStep 2 of the Meeting Notes Formatter Agent.\n\nThis file turns a raw transcript into three things the AI extracts for\nyou: the decisions that were made, the action items (each with an owner\nand a deadline), and a short summary.\n\"\"\"\n\nfrom sdt_ai import ask_ai\n\n# Placeholder words the AI sometimes writes instead of just admitting a\n# field wasn't mentioned. We treat all of these the same way: \"nobody\n# said, so don't guess\" - never invent a name or a date to fill the gap.\nUNCLEAR_VALUES = {\n    \"\", \"n/a\", \"na\", \"none\", \"tbd\", \"not specified\", \"unspecified\",\n    \"unclear\", \"unknown\", \"?\", \"-\",\n}\n\n\ndef build_prompt(transcript_text):\n    \"\"\"\n    Writes the instructions we send to the AI.\n\n    The [ACTIONS] section asks for one specific plain-text shape per\n    line - \"Task: ... | Owner: ... | Deadline: ...\" - instead of JSON.\n    A stray comma in a task description, or an AI that decides to wrap\n    its reply in ```json fences, breaks a JSON parser outright. A\n    marker-based, line-by-line format degrades instead of exploding: a\n    mis-formed line just fails to match cleanly, and every other line\n    still parses fine (see _parse_action_line below).\n    \"\"\"\n    return f\"\"\"Read the meeting transcript below and extract three things.\n\nFormat your answer EXACTLY like this:\n\n[DECISIONS]\n- one decision per line, as a short plain sentence\n- if no decisions were made, write a single line: None recorded\n\n[ACTIONS]\nTask: <what needs to be done> | Owner: <who is responsible> | Deadline: <when it's due>\n(one line per action item, in that exact \"Task: ... | Owner: ... | Deadline: ...\" shape)\nIf the transcript does not clearly say who owns an item, write \"Unassigned\" as the\nOwner - do not guess a name. If no deadline was mentioned, write \"No deadline set\" as\nthe Deadline. If there are no action items at all, write a single line: None recorded\n\n[SUMMARY]\na plain 2-3 sentence summary of what the meeting was about\n\n[END]\n\nDo not add any explanation, introduction or closing remark outside these sections.\nDo not invent people, dates or decisions that are not in the transcript below.\n\nTRANSCRIPT:\n{transcript_text}\"\"\"\n\n\ndef _normalize(value, default):\n    \"\"\"A blank or vague AI answer (\"TBD\", \"N/A\", \"\") becomes one clear default.\"\"\"\n    if value.strip().lower() in UNCLEAR_VALUES:\n        return default\n    return value.strip()\n\n\ndef _parse_action_line(line):\n    \"\"\"\n    Turns one \"Task: ... | Owner: ... | Deadline: ...\" line into a dict:\n\n        {\"task\": \"Send the proposal\", \"owner\": \"Unassigned\", \"deadline\": \"No deadline set\"}\n\n    Built to survive an AI that doesn't follow the format perfectly - a\n    missing label, a missing \"|\", or a blank value all fall back to a\n    sensible default instead of raising an exception mid-run. Returns\n    None only if the line has no usable text in it at all (e.g. a\n    stray blank line inside the [ACTIONS] block).\n    \"\"\"\n    result = {\"task\": \"\", \"owner\": \"Unassigned\", \"deadline\": \"No deadline set\"}\n    leftover_text = []\n\n    for part in line.split(\"|\"):\n        part = part.strip()\n        low = part.lower()\n        if low.startswith(\"task:\"):\n            result[\"task\"] = part.split(\":\", 1)[1].strip()\n        elif low.startswith(\"owner:\"):\n            result[\"owner\"] = _normalize(part.split(\":\", 1)[1], \"Unassigned\")\n        elif low.startswith(\"deadline:\"):\n            result[\"deadline\"] = _normalize(part.split(\":\", 1)[1], \"No deadline set\")\n        elif part:\n            # No recognised label on this chunk - the AI may have skipped\n            # the \"Task:\" prefix entirely. Keep the text in case nothing\n            # else on the line turns out to carry the task description.\n            leftover_text.append(part)\n\n    if not result[\"task\"]:\n        result[\"task\"] = \" \".join(leftover_text).strip()\n\n    return result if result[\"task\"] else None\n\n\ndef parse_reply(reply):\n    \"\"\"\n    Turns the AI's one long answer into a dictionary:\n\n        {\"decisions\": [...], \"actions\": [{\"task\", \"owner\", \"deadline\"}, ...], \"summary\": \"...\"}\n\n    Mirrors generator.py's split_posts() in the Social Post Generator\n    project: [MARKER] sections we recognise are collected, anything\n    else (stray commentary, code fences) is quietly dropped instead of\n    crashing the whole program.\n    \"\"\"\n    sections = {\"DECISIONS\": [], \"ACTIONS\": [], \"SUMMARY\": []}\n    current = None\n\n    for raw_line in reply.splitlines():\n        line = raw_line.strip()\n        marker = line.strip(\"[]\").upper()\n        is_marker = line.startswith(\"[\") and line.endswith(\"]\")\n\n        # [END] tells us the sections are finished. Without it, a friendly\n        # sign-off like \"Let me know if you need changes!\" gets glued onto\n        # the summary and saved straight into the output file.\n        if is_marker and marker == \"END\":\n            break\n        if is_marker and marker in sections:\n            current = marker\n            continue\n        if current is None:\n            # Text before the first recognised marker (a stray greeting,\n            # for example) isn't part of any section - ignore it.\n            continue\n        if line.startswith(\"```\"):\n            # The AI sometimes wraps its whole answer in code fences.\n            continue\n        if line:\n            sections[current].append(line)\n\n    decisions = [\n        d.lstrip(\"-* \").strip()\n        for d in sections[\"DECISIONS\"]\n        if d.lstrip(\"-* \").strip().lower() != \"none recorded\"\n    ]\n\n    actions = []\n    for line in sections[\"ACTIONS\"]:\n        if line.strip().lower() == \"none recorded\":\n            continue\n        parsed = _parse_action_line(line)\n        if parsed:\n            actions.append(parsed)\n\n    summary = \" \".join(sections[\"SUMMARY\"]).strip()\n\n    if not decisions and not actions and not summary:\n        raise ValueError(\n            \"The AI replied, but not in the format we asked for.\\n\"\n            \"Run it again - this usually fixes itself.\\n\"\n            \"If it keeps happening, print(reply) to see what came back.\"\n        )\n\n    return {\"decisions\": decisions, \"actions\": actions, \"summary\": summary}\n\n\ndef format_notes(transcript_text):\n    \"\"\"\n    The main function. Give it a raw transcript, get back a parsed dict\n    ready for output.py to render.\n\n        result = format_notes(transcript_text)\n        print(result[\"summary\"])\n    \"\"\"\n    prompt = build_prompt(transcript_text)\n\n    # max_tokens caps how long the AI's answer may be, which caps what this\n    # costs you. 900 comfortably covers a summary plus a dozen action items -\n    # far more than a typical meeting produces.\n    reply = ask_ai(\n        prompt,\n        max_tokens=900,\n        project=\"meeting-notes-formatter-agent\",\n    )\n\n    return parse_reply(reply)\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the parsing works, entirely\n    # offline - no AI call, no API usage:  python formatter.py\n\n    print(\"--- Well-formed reply ---\")\n    good_reply = \"\"\"[DECISIONS]\n- Ship the v2 API on the 15th instead of the 10th\n- Drop the CSV export feature from this release\n\n[ACTIONS]\nTask: Update the release notes | Owner: Priya | Deadline: Friday\nTask: Notify the beta testers about the new date | Owner: Unassigned | Deadline: No deadline set\n\n[SUMMARY]\nThe team pushed the v2 API launch back five days to finish load testing,\nand agreed to cut CSV export from this release to protect the new date.\n\n[END]\"\"\"\n    result = parse_reply(good_reply)\n    print(f\"{len(result['decisions'])} decisions, {len(result['actions'])} actions\")\n    for action in result[\"actions\"]:\n        print(\" \", action)\n    print(\"Summary:\", result[\"summary\"])\n\n    # Now a reply an AI actually sends sometimes: no [SUMMARY] marker at\n    # all, one action item with no Owner/Deadline labels whatsoever, one\n    # with a vague \"TBD\" owner, one with no labels at all, and the whole\n    # thing wrapped in a markdown code fence. This must not crash - every\n    # gap should become a clear default, never an invented name or date.\n    print(\"\\n--- Malformed reply (missing [SUMMARY], missing/vague labels) ---\")\n    malformed_reply = \"\"\"```\n[DECISIONS]\n- Move the launch to Q3\n\n[ACTIONS]\nTask: Follow up with legal about the contract\nTask: Book the venue | Owner: TBD | Deadline: next Tuesday\nJust remember to lock the meeting room before Friday\n\n[END]\n```\"\"\"\n    result = parse_reply(malformed_reply)\n    print(f\"{len(result['decisions'])} decisions, {len(result['actions'])} actions\")\n    for action in result[\"actions\"]:\n        print(\" \", action)\n    print(\"Summary (should be blank, not crashed):\", repr(result[\"summary\"]))\n\n    # A reply with none of the markers at all - e.g. the AI ignored the\n    # instructions completely. We can't recover anything from this, so\n    # we raise a clear error instead of silently returning an empty result.\n    print(\"\\n--- Reply with no recognisable markers at all ---\")\n    try:\n        parse_reply(\"Sorry, I can't help with that request.\")\n        print(\"ERROR: should have raised ValueError\")\n    except ValueError as problem:\n        print(\"Correctly raised an error:\")\n        print(problem)\n",
          "verify": "Run `python formatter.py` (no AI call, no API usage - this only tests the parsing logic against fake replies). You should see:\n--- Well-formed reply ---\n2 decisions, 2 actions\n  {'task': 'Update the release notes', 'owner': 'Priya', 'deadline': 'Friday'}\n  {'task': 'Notify the beta testers about the new date', 'owner': 'Unassigned', 'deadline': 'No deadline set'}\nSummary: The team pushed the v2 API launch back five days...\n\n--- Malformed reply (missing [SUMMARY], missing/vague labels) ---\n1 decisions, 3 actions\n  {'task': 'Follow up with legal about the contract', 'owner': 'Unassigned', 'deadline': 'No deadline set'}\n  {'task': 'Book the venue', 'owner': 'Unassigned', 'deadline': 'next Tuesday'}\n  {'task': 'Just remember to lock the meeting room before Friday', 'owner': 'Unassigned', 'deadline': 'No deadline set'}\nSummary (should be blank, not crashed): ''\n\n--- Reply with no recognisable markers at all ---\nCorrectly raised an error:\nThe AI replied, but not in the format we asked for.\nRun it again - this usually fixes itself.\nIf it keeps happening, print(reply) to see what came back.",
          "instruction": "Create `formatter.py` with this code:"
        }
      ],
      "title": "Ask the AI to extract decisions, actions, and a summary",
      "number": 3,
      "goFurther": "Break it on purpose: in formatter.py's self-test, take the `malformed_reply` string and delete the `[SUMMARY]` marker AND every remaining `Owner:`/`Deadline:` label, leaving one action as a completely bare sentence with no labels at all. Run `python formatter.py` again - confirm nothing crashes, that bare-sentence action still shows up with `Unassigned` and `No deadline set`, and write a one-line comment explaining why that's safer than the AI guessing a name.",
      "description": "This is the heart of the project - turning a rambling transcript into decisions, action items with owners and deadlines, and a summary. It's also the one place a project like this can go quietly wrong: an AI that skips a section, or invents an owner nobody mentioned. Build the prompt and the parser together so you can prove they survive a bad reply before you ever make a real AI call."
    },
    {
      "time": "20 min",
      "steps": [
        {
          "prompt": "\"\"\"\nStep 3 of the Meeting Notes Formatter Agent.\n\nThis file turns the dictionary formatter.py produces into clean,\nreadable Markdown - either as a string to print, or as a saved .md file\nyou can drop straight into Notion, GitHub, Slack, or anywhere else that\nrenders Markdown.\n\"\"\"\n\nimport os\nfrom datetime import datetime\n\n\ndef render_markdown(parsed, title=\"Meeting Notes\"):\n    \"\"\"\n    Turns {\"decisions\": [...], \"actions\": [...], \"summary\": \"...\"} into\n    a Markdown string.\n\n        markdown = render_markdown(result)\n        print(markdown)\n\n    Works even when a section is empty - a very short transcript that\n    produced no decisions still gets a readable document with a \"no\n    decisions recorded\" line, rather than a header with nothing under it.\n    \"\"\"\n    lines = [f\"# {title}\", \"\"]\n\n    lines.append(\"## Summary\")\n    lines.append(parsed[\"summary\"] if parsed[\"summary\"] else \"_No summary available._\")\n    lines.append(\"\")\n\n    lines.append(\"## Decisions\")\n    if parsed[\"decisions\"]:\n        lines.extend(f\"- {d}\" for d in parsed[\"decisions\"])\n    else:\n        lines.append(\"_No decisions recorded._\")\n    lines.append(\"\")\n\n    lines.append(\"## Action Items\")\n    if parsed[\"actions\"]:\n        lines.append(\"| Task | Owner | Deadline |\")\n        lines.append(\"|------|-------|----------|\")\n        for action in parsed[\"actions\"]:\n            # A \"|\" inside the AI's own wording would split a Markdown\n            # table cell in two, so swap any it wrote for a dash.\n            task = action[\"task\"].replace(\"|\", \"-\")\n            owner = action[\"owner\"].replace(\"|\", \"-\")\n            deadline = action[\"deadline\"].replace(\"|\", \"-\")\n            lines.append(f\"| {task} | {owner} | {deadline} |\")\n    else:\n        lines.append(\"_No action items recorded._\")\n    lines.append(\"\")\n\n    return \"\\n\".join(lines)\n\n\ndef save_markdown(markdown_text, output_dir=\"notes_output\"):\n    \"\"\"\n    Saves markdown_text to a timestamped .md file inside output_dir\n    (created if it doesn't exist yet), and returns the path it used.\n\n        path = save_markdown(markdown)\n        print(f\"Saved to {path}\")\n\n    Timestamping the filename (instead of always writing e.g.\n    meeting_notes.md) means running this twice in a row keeps both\n    sets of notes, instead of silently overwriting the first one -\n    the exact kind of thing that's easy to miss on a Friday afternoon.\n    \"\"\"\n    os.makedirs(output_dir, exist_ok=True)\n    timestamp = datetime.now().strftime(\"%Y%m%d_%H%M%S\")\n    path = os.path.join(output_dir, f\"meeting_notes_{timestamp}.md\")\n\n    with open(path, \"w\", encoding=\"utf-8\") as f:\n        f.write(markdown_text)\n\n    return path\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check rendering and saving work,\n    # entirely offline:  python output.py\n    sample = {\n        \"decisions\": [\"Ship v2 on the 15th\", \"Drop CSV export from this release\"],\n        \"actions\": [\n            {\"task\": \"Update the release notes\", \"owner\": \"Priya\", \"deadline\": \"Friday\"},\n            {\"task\": \"Notify beta testers\", \"owner\": \"Unassigned\", \"deadline\": \"No deadline set\"},\n        ],\n        \"summary\": \"The team pushed the launch back five days to finish load testing.\",\n    }\n\n    markdown = render_markdown(sample)\n    print(markdown)\n\n    print(\"\\n--- Testing a fully empty result (nothing recorded anywhere) ---\")\n    empty = {\"decisions\": [], \"actions\": [], \"summary\": \"\"}\n    print(render_markdown(empty))\n\n    print(\"--- Saving to disk ---\")\n    saved_path = save_markdown(markdown)\n    print(f\"Saved to: {saved_path}\")\n    with open(saved_path, encoding=\"utf-8\") as f:\n        saved_content = f.read()\n    assert saved_content == markdown, \"Saved file doesn't match what we rendered!\"\n    print(\"Confirmed: saved file matches the rendered Markdown.\")\n",
          "verify": "Run `python output.py`. You should see the rendered Markdown printed twice (once with real sample data, once with every section empty and showing '_No summary available._' / '_No decisions recorded._' / '_No action items recorded._'), then:\n--- Saving to disk ---\nSaved to: notes_output/meeting_notes_<timestamp>.md   (with \\ instead of / on Windows)\nConfirmed: saved file matches the rendered Markdown.\n\nOpen the new file inside `notes_output/` and confirm the Action Items section is a real Markdown table with | Task | Owner | Deadline | columns.",
          "instruction": "Create `output.py` with this code:"
        }
      ],
      "title": "Render the result as Markdown",
      "number": 4,
      "goFurther": "Ask the AI for a fourth `[ATTENDEES]` marker in formatter.py's prompt, parse it the same way as [DECISIONS], and add an `## Attendees` section to render_markdown().",
      "description": "A Python dictionary is useless to hand a teammate. This build turns the parsed decisions/actions/summary into a Markdown document with a real table, and saves it to a timestamped file so running the tool twice never overwrites your last set of notes."
